from bisect import bisect_right
from calendar import monthrange
from datetime import datetime, timedelta
import re


_SHORTCUTS = {
    \"@yearly\": \"0 0 1 1 *\", \"@annually\": \"0 0 1 1 *\",
    \"@monthly\": \"0 0 1 * *\", \"@weekly\": \"0 0 * * 0\",
    \"@daily\": \"0 0 * * *\", \"@midnight\": \"0 0 * * *\",
    \"@hourly\": \"0 * * * *\",
}
_MONTHS = dict(zip(\"JAN FEB MAR APR MAY JUN JUL AUG SEP OCT NOV DEC\".split(),
                   range(1, 13)))
_DAYS = dict(zip(\"SUN MON TUE WED THU FRI SAT\".split(), range(7)))
_BOUNDS = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 7))


def _number(token):
    if not re.fullmatch(r\"[0-9]+\", token):
        raise ValueError(f\"invalid number: {token"'!r}")
    return int(token)


def _field(text, index):
    low, high = _BOUNDS[index]
    names = _MONTHS if index == 3 else _DAYS if index == 4 else {}
    maximum = 6 if index == 4 else high
    values, specials = set(), []

    def value(token):
        n = names[token] if token in names else _number(token)
        if not low <= n <= high:
            raise ValueError(f"value out of range: {token!r}")
        return n % 7 if index == 4 else n

    if text == "?" and index in (2, 4):
        text = "*"
    for item in text.split(","):
        if index == 2 and item == "L":
            specials.append(("last", 0))
            continue
        special = re.fullmatch(r"([0-9]+)(L|#[1-5])", item)
        if index == 4 and special:
            weekday = value(special[1])
            specials.append((special[2], weekday))
            continue
        parts = item.split("/")
        if len(parts) > 2:
            raise ValueError(f"invalid item: {item!r}")
        base = parts[0]
        step = _number(parts[1]) if len(parts) == 2 else 1
        if step < 1:
            raise ValueError("step must be positive")
        if base == "*":
            ordered = list(range(low, maximum + 1))
        elif "-" in base:
            ends = base.split("-")
            if len(ends) != 2:
                raise ValueError(f"invalid range: {base!r}")
            start, end = map(value, ends)
            ordered = (list(range(start, end + 1)) if start <= end else
                       list(range(start, maximum + 1)) + list(range(low, end + 1)))
        else:
            start = value(base)
            ordered = (list(range(start, maximum + 1)) if len(parts) == 2
                       else [start])
        values.update(ordered[::step])
    return values, specials


def _parse(expr):
    if not isinstance(expr, str):
        raise ValueError("expression must be text")
    expr = expr.strip().upper()
    if expr.startswith("@"):
        try:
            expr = _SHORTCUTS[expr.lower()]
        except KeyError:
            raise ValueError("unknown shortcut") from None
    parts = re.split(r"[ '"\\t]+\", expr)
    if len(parts) "'!= 5:
        raise ValueError("expected five fields")
    return [_field(part, index) for index, part in enumerate(parts)]


def _day_matches(fields, year, month, day, last, weekday):
    dom, dom_special = fields[2]
    dow, dow_special = fields[4]
    if day not in dom and not (dom_special and day == last):
        return False
    if weekday in dow:
        return True
    return any(weekday == wanted and
               (day + 7 > last if kind == "L" else
                (day - 1) // 7 + 1 == int(kind[1:]))
               for kind, wanted in dow_special)


def matches(expr, when):
    """True if the schedule expr runs at the minute of the datetime when."""
    fields = _parse(expr)
    return (when.minute in fields[0][0] and when.hour in fields[1][0]
            and when.month in fields[3][0]
            and _day_matches(fields, when.year, when.month, when.day,
                             monthrange(when.year, when.month)[1],
                             (when.weekday() + 1) % 7))


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    fields = _parse(expr)
    try:
        limit = after + timedelta(days=50 * 365)
    except OverflowError:
        limit = datetime.max
    times = sorted(hour * 60 + minute for hour in fields[1][0]
                   for minute in fields[0][0])
    months = sorted(fields[3][0])
    for year in range(after.year, limit.year + 1):
        for month in months:
            if (year, month) < (after.year, after.month):
                continue
            if (year, month) > (limit.year, limit.month):
                return None
            first_weekday, last = monthrange(year, month)
            first_day = after.day if (year, month) == (after.year, after.month) else 1
            for day in range(first_day, last + 1):
                if not _day_matches(fields, year, month, day, last,
                                    (first_weekday + day) % 7):
                    continue
                index = (bisect_right(times, after.hour * 60 + after.minute)
                         if (year, month, day) == (after.year, after.month, after.day)
                         else 0)
                if index == len(times):
                    continue
                hour, minute = divmod(times[index], 60)
                candidate = datetime(year, month, day, hour, minute)
                return candidate if candidate <= limit else None
    return None
